#!/usr/bin/env python3
"""Dependency-free bilingual static site builder. Run: python3 build.py"""
import json, shutil, html, sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).parent / 'src'))
from content import CONTENT
ROOT=Path(__file__).resolve().parent
C=json.loads((ROOT/'site.config.json').read_text()); OUT=ROOT/'dist'
if OUT.exists(): shutil.rmtree(OUT)
OUT.mkdir(); shutil.copytree(ROOT/'src/assets',OUT/'assets')
for file in ['styles.css','app.js']: shutil.copy(ROOT/'src'/file,OUT/file)
(OUT/'config.js').write_text('window.NIORO_CONFIG = '+json.dumps({'email':C['email'],'formEndpoint':C['formEndpoint']})+';\n')
E=html.escape
PAGES=['','about','solutions','markets','partners','contact','privacy','solutions/trade','solutions/technology','solutions/logistics','solutions/government','solutions/sourcing','solutions/furniture','solutions/applications','global-network','corporate-profile']
def url(l,p=''): return f'/{l}/'+(p+'/' if p else '')
def link(l,p,text,cls=''): return f'<a class="{cls}" href="{url(l,p)}">{E(text)}</a>'
def logo(l,dark=False): return f'<a class="brand" href="{url(l)}" aria-label="Nioro Resources — '+('Home' if l=='en' else 'Accueil')+f'"><img src="/assets/logo-{"reversed" if dark else "primary"}.png" width="2400" height="920" alt="Nioro Resources"></a>'
def mapview(l):
 t=CONTENT[l]
 return f'''<figure class="map"><div class="map-top"><span>{'OUR MARKET FOCUS' if l=='en' else 'NOS MARCHÉS PRIORITAIRES'}</span><span>US / AF / EU / AS</span></div><svg viewBox="0 0 930 470" role="img" aria-label="{E(t['mapLabel'])}"><image href="/assets/world.svg" width="930" height="470"/><path class="route" d="M185 140 Q330 24 477 110 M477 110 Q540 180 490 265 M490 265 Q590 88 715 154"/><circle cx="185" cy="140" r="6" class="point"/><circle cx="477" cy="110" r="6" class="point"/><circle cx="490" cy="265" r="6" class="point"/><circle cx="715" cy="154" r="6" class="point"/><text x="80" y="182">{'UNITED STATES' if l=='en' else 'ÉTATS-UNIS'}</text><text x="438" y="82">EUROPE</text><text x="475" y="305">{'AFRICA' if l=='en' else 'AFRIQUE'}</text><text x="730" y="192">{'ASIA' if l=='en' else 'ASIE'}</text></svg><div class="map-bottom"><strong>{'United States / Africa / Europe / Asia' if l=='en' else 'États-Unis / Afrique / Europe / Asie'}</strong><p>{t['mapFoot']}</p></div></figure>'''
def network(l):
 t=CONTENT[l];countries=t['countries'];shapes=json.loads((ROOT/'src/country-paths.json').read_text())
 polygons=''.join(f'<path class="country-shape" data-country-shape="{c["id"]}" data-map-country="{c["id"]}" d="{shapes[c["id"]]}"/>' for c in countries)
 markers=''
 for c in countries:
  x=(c['lon']+170)*2.65;y=(80-c['lat'])*3.5
  shape=(f'<rect x="{x-6}" y="{y-6}" width="12" height="12"/>' if c['kind']=='hq' else f'<path d="M{x} {y-8}l8 8-8 8-8-8Z"/>' if c['kind']=='sourcing' else f'<circle cx="{x}" cy="{y}" r="6"/>')
  markers+=f'<a href="#country-{c["id"]}" data-map-country="{c["id"]}" aria-label="{E(c["name"]+": "+c["status"])}"><circle class="map-hit" cx="{x}" cy="{y}" r="14"/>{shape}<title>{E(c["name"])}</title></a>'
 controls=''.join(f'<a class="country-control" href="#country-{c["id"]}" data-map-country="{c["id"]}" aria-controls="country-{c["id"]}">{c["name"]}</a>' for c in countries)
 panels=''.join(f'<article class="country-panel" id="country-{c["id"]}" data-country-panel="{c["id"]}" tabindex="-1"><p class="eyebrow">{c["region"]}</p><h2>{c["name"]}</h2><p class="network-status {c["kind"]}">{c["status"]}</p><h3>{"Business focus" if l=="en" else "Domaines d’activité"}</h3><p>{c["focus"]}</p><p>{c["detail"]}</p>{link(l,"contact",t["discuss"],"text-link")}</article>' for c in countries)
 return f'''<section class="wrap network-section" data-network><p class="lead">{t['mapHelp']}</p><div class="network-layout"><div><figure class="map network-map"><div class="map-top"><span>{t['nav'][2]}</span><span>US / AF / EU / AS</span></div><svg viewBox="0 0 930 470" aria-label="{'Interactive map of six countries in the Nioro network' if l=='en' else 'Carte interactive de six pays du réseau Nioro'}"><image href="/assets/world.svg" width="930" height="470"/>{polygons}<g class="network-markers">{markers}</g></svg><figcaption>{'Select a highlighted country or use the country links below.' if l=='en' else 'Sélectionnez un pays mis en évidence ou utilisez les liens ci-dessous.'}</figcaption></figure><nav class="country-controls" aria-label="{'Network countries' if l=='en' else 'Pays du réseau'}">{controls}</nav></div><div class="country-panels" aria-live="polite" aria-atomic="true">{panels}</div></div><div class="network-legend"><span class="hq">{'Headquarters' if l=='en' else 'Siège'}</span><span class="commercial">{'Commercial relationships' if l=='en' else 'Relations commerciales'}</span><span class="sourcing">{'Sourcing partners' if l=='en' else 'Partenaires de sourcing'}</span><span class="target">{'Other West African markets: development targets' if l=='en' else 'Autres marchés ouest-africains : objectifs de développement'}</span></div><p class="network-note">{t['networkNote']}</p></section><section class="section muted"><div class="wrap"><h2>{t['advantageTitle']}</h2><p class="lead">{t['advantage']}</p><p class="network-tagline">{t['networkTagline']}</p></div></section>'''
def profile(l):
 t=CONTENT[l]
 headings=['Region','Country','Role','Business focus'] if l=='en' else ['Région','Pays','Rôle','Domaines d’activité']
 table='<div class="table-scroll" tabindex="0" role="region" aria-label="'+t['nav'][2]+'"><table><caption>'+t['nav'][2]+'</caption><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headings)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(c[k])+'</td>' for k in ['region','name','status','focus'])+'</tr>' for c in t['countries'])+'</tbody></table></div>'
 return intro(l,t['profileLabel'],'Nioro Resources LLC',t['footerLine'])+f'<section class="wrap section compact profile-body"><p class="lead">{t["aboutText"]}</p><div class="facts"><span>{t["location"]}</span><span>{t["established"]}</span><a href="mailto:{C["email"]}">{C["email"]}</a></div><h2>{t["solutionsTitle"]}</h2>{rows([(s["title"],s["short"]) for s in t["solutions"]])}{table}<p>{t["networkNote"]}</p><h2>{t["advantageTitle"]}</h2><p>{t["advantage"]}</p><aside class="scope"><h2>{t["scopeLabel"]}</h2><p>{t["scopeText"]}</p><p>{next(s["note"] for s in t["solutions"] if s["slug"]=="government")}</p></aside></section>'

def intro(l,label,title,desc):return f'<section class="page-intro wrap"><p class="eyebrow">{E(label)}</p><h1>{E(title)}</h1><p class="lead">{E(desc)}</p></section>'
def rows(items):return '<div class="detail-rows">'+''.join(f'<article><h3>{E(a)}</h3><p>{E(b)}</p></article>' for a,b in items)+'</div>'
def solutions(l,exclude=''):
 t=CONTENT[l]
 return '<div class="solution-list">'+''.join(f'<a class="solution" href="{url(l,"solutions/"+s["slug"])}"><div><h3>{E(s["title"])}</h3><p>{E(s["short"])}</p></div><span class="text-link">{t["learn"]}</span></a>' for s in t['solutions'] if s['slug']!=exclude)+'</div>'
def cta(l):
 t=CONTENT[l];return f'<section class="cta"><div class="wrap cta-inner"><div><h2>{E(t["ctaTitle"])}</h2><p>{E(t["ctaText"])}</p></div>{link(l,"contact",t["discuss"],"button gold")}</div></section>'
def form(l,partner=False):
 t=CONTENT[l]; fields=t['fields'];htmls=[]
 for name in ['name','email','organization','country','website']:
  typ={'email':'email','website':'url'}.get(name,'text');auto={'name':'name','email':'email','organization':'organization','country':'country-name','website':'url'}[name]
  htmls.append(f'<div class="field"><label for="{name}">{E(fields[name])}</label><input id="{name}" name="{name}" type="{typ}" autocomplete="{auto}" maxlength="{254 if name=="email" else 160}" {"required" if name!="website" else ""}></div>')
 cats=''.join(f'<option value="{i}" {"selected" if (partner and i==5) else ""}>{E(v)}</option>' for i,v in enumerate(t['categories']))
 return f'''<div class="form-block" id="inquiry"><h2>{E(t['partnerFormTitle'] if partner else t['formTitle'])}</h2><p>{E(t['formIntro'])}</p><form data-inquiry data-partner="{str(partner).lower()}"><div class="form-grid">{''.join(htmls)}<div class="field"><label for="category">{fields['category']}</label><select id="category" name="category">{cats}</select></div><div class="field full"><label for="message">{fields['message']}</label><textarea id="message" name="message" rows="6" minlength="20" maxlength="4000" required aria-describedby="message-help"></textarea><small id="message-help">{'20–4,000 characters. Include scope, location and timing.' if l=='en' else '20 à 4 000 caractères. Précisez le besoin, le lieu et le calendrier.'}</small></div></div><div class="honey" aria-hidden="true"><label>Leave empty<input name="fax" tabindex="-1" autocomplete="off"></label></div><label class="consent"><input type="checkbox" name="consent" required><span>{E(t['consent'])} {link(l,'privacy',t['privacy'],'inline-link')}</span></label><p class="form-note" id="form-note" data-email-note="{E(t['emailNote'])}" data-direct-note="{E(t['directNote'])}">{E(t['emailNote'])}</p><button class="button" type="submit" data-prepare="{E(t['prepare'])}" data-send="{E(t['send'])}">{E(t['prepare'])}</button><div class="form-result" role="status" aria-live="polite" tabindex="-1" hidden></div><noscript><p>{'JavaScript is required to prepare the form. Email us directly:' if l=='en' else 'JavaScript est nécessaire pour préparer le formulaire. Écrivez-nous directement :'} <a href="mailto:{C['email']}">{C['email']}</a></p></noscript></form></div>'''
def legacy_catalog(l):
 return '<p><a class="inline-link" href="/legacy/#games">'+('Our apps and games' if l=='en' else 'Nos applications et jeux')+'</a></p>'
def body(l,p):
 t=CONTENT[l]
 if p=='':
  return f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">{t['eyebrow']}</p><h1>{t['homeTitle']}</h1><p class="lead">{t['heroLead']}</p><div class="actions">{link(l,'solutions',t['explore'],'button')}{link(l,'partners',t['partner'],'text-link')}</div></div>{mapview(l)}</section><div class="facts wrap"><span>{t['aboutLabel']}</span><span>{t['location']}</span><span>{t['established']}</span></div><section class="section wrap split"><p class="eyebrow">{t['aboutLabel']}</p><div><h2>{t['aboutTitle']}</h2><p class="lead">{t['aboutText']}</p>{link(l,'about',t['aboutLink'],'text-link')}</div></section><section class="section muted"><div class="wrap"><div class="section-head"><h2>{t['solutionsTitle']}</h2><p>{t['solutionsLead']}</p></div>{solutions(l)}</div></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">{t['processLabel']}</p><h2>{t['processTitle']}</h2></div></div><div class="steps">{''.join(f'<article><h3>{a}</h3><p>{b}</p></article>' for a,b in t['steps'])}</div></section><section class="section market-section"><div class="wrap"><div class="section-head"><h2>{t['marketsTitle']}</h2><p>{t['marketsLead']}</p></div><div class="market-cards">{''.join(f'<article><p class="eyebrow">{t["marketStatus"][i]}</p><h3>{v}</h3><p>{t["marketText"][i]}</p></article>' for i,v in enumerate(t['markets']))}</div>{link(l,'global-network',t['nav'][2],'text-link')}</div></section>{cta(l)}'''
 if p=='about':
  return intro(l,t['nav'][0],t['aboutPageTitle'],t['aboutIntro'])+f'<div class="wrap profile-link">{link(l,"corporate-profile",t["profileLabel"],"text-link")}</div>'+f'<section class="section muted"><div class="wrap two-col"><article><p class="eyebrow">{t["missionTitle"]}</p><h2>{t["mission"]}</h2></article><article><p class="eyebrow">{t["visionTitle"]}</p><p class="lead">{t["vision"]}</p></article></div></section><section class="section wrap split"><h2>{t["valuesTitle"]}</h2>{rows(t["values"])}</section><section class="scope wrap"><h2>{t["scopeTitle"]}</h2><p>{t["scopeText"]}</p></section>'+cta(l)
 if p=='solutions': return intro(l,t['nav'][1],t['solutionsTitle'],t['solutionsLead'])+f'<section class="wrap section compact">{solutions(l)}</section>'+cta(l)
 if p.startswith('solutions/'):
  s=next(s for s in t['solutions'] if s['slug']==p.split('/')[1]);idx=t['solutions'].index(s)
  return intro(l,t['nav'][1],s['title'],s['intro'])+f'<section class="section muted"><div class="wrap split"><div><p class="eyebrow">{t["serviceFocus"]}</p><h2>{s["focus"]}</h2></div>{rows(s["items"])}</div></section><section class="wrap section two-col"><div><h2>{t["startWith"]}</h2><p>{s["need"]}</p><a class="button" href="{url(l,"contact")}?category={s["category"]}#inquiry">{t["discuss"]}</a></div><aside class="scope"><h3>{t["scopeLabel"]}</h3><p>{s["note"]}</p>{legacy_catalog(l) if s["slug"]=="applications" else ""}</aside></section><section class="section wrap compact"><h2>{t["otherSolutions"]}</h2>{solutions(l,s["slug"])}</section>'
 if p in ['markets','global-network']: return intro(l,t['nav'][2],t['marketsTitle'],t['marketsLead'])+network(l)+cta(l)
 if p=='corporate-profile': return profile(l)
 if p=='partners': return intro(l,t['nav'][3],t['partnersTitle'],t['partnersLead'])+f'<section class="wrap section contact-grid"><aside>{rows(t["partnersItems"])}</aside>{form(l,True)}</section>'+cta(l)
 if p=='contact': return intro(l,t['nav'][4],t['contactTitle'],t['contactLead'])+f'<section class="wrap section compact contact-grid"><aside class="contact-aside"><p class="eyebrow">{t["directEmail"]}</p><a class="email-link" href="mailto:{C["email"]}">{C["email"]}</a><hr><h2>{t["location"]}</h2><p>{t["contactSide"]}</p><p>{t["established"]}</p></aside>{form(l)}</section>'
 if p=='privacy':return intro(l,t['aboutLabel'],t['privacyTitle'],'')+'<section class="wrap section compact prose">'+''.join(f'<article><h2>{E(a)}</h2><p>{E(b)}</p></article>' for a,b in t['privacySections'])+'</section>'
 return intro(l,'404',t['notFound'],'')+f'<section class="wrap section">{link(l,"",t["backHome"],"button")}</section>'
def render(l,p):
 t=CONTENT[l]; other='fr' if l=='en' else 'en'; navpaths=['about','solutions','global-network','partners','contact']; names=dict(zip(navpaths,t['nav'])); names.update({'markets':t['nav'][2],'corporate-profile':t['profileLabel']})
 title=t['homeTitle'] if not p else names.get(p,t['privacyTitle'] if p=='privacy' else next((s['title'] for s in t['solutions'] if p=='solutions/'+s['slug']),t['notFound']))
 desc=t['heroLead'] if not p else (next((s['short'] for s in t['solutions'] if p=='solutions/'+s['slug']),t.get({'about':'aboutIntro','solutions':'solutionsLead','markets':'marketsLead','global-network':'marketsLead','partners':'partnersLead','contact':'contactLead'}.get(p,''),t['aboutText'])))
 altpath=p if p in PAGES else ''
 canonical=C['origin'].rstrip('/')+(url(l,'global-network' if p=='markets' else p) if p in PAGES else '/404.html')
 nav=''.join(f'<a href="{url(l,np)}" {"aria-current=page" if p==np or p.startswith(np+"/") else ""}>{label}</a>' for np,label in zip(navpaths,t['nav']))
 # Structured data deliberately omits unverified registration, clients and awards.
 schema={'@context':'https://schema.org','@type':'Organization','name':'Nioro Resources LLC','url':C['origin'],'logo':C['origin']+'/assets/logo-primary.png','foundingDate':'2020','email':C['email'],'address':{'@type':'PostalAddress','addressRegion':'Arizona','addressCountry':'US'}}
 return f'''<!doctype html><html lang="{l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} | Nioro Resources</title><meta name="description" content="{E(desc)}"><meta name="robots" content="{'index,follow' if C['indexable'] else 'noindex,nofollow'}"><meta name="theme-color" content="#0b2545"><link rel="canonical" href="{canonical}"><link rel="alternate" hreflang="en" href="{C['origin']+url('en',altpath)}"><link rel="alternate" hreflang="fr" href="{C['origin']+url('fr',altpath)}"><link rel="alternate" hreflang="x-default" href="{C['origin']+url('en',altpath)}"><meta property="og:type" content="website"><meta property="og:title" content="{E(title)} | Nioro Resources"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{C['origin']}/assets/logo-primary.png"><meta property="og:locale" content="{'en_US' if l=='en' else 'fr_FR'}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="preload" href="/assets/montserrat-400.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/styles.css"><script src="/config.js" defer></script><script src="/app.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body><a class="skip" href="#main">{t['skip']}</a><header class="header"><div class="wrap nav-wrap">{logo(l)}<button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">{t['menu']}</button><nav id="main-nav" aria-label="{'Main navigation' if l=='en' else 'Navigation principale'}">{nav}</nav><div class="language" aria-label="{'Language' if l=='en' else 'Langue'}"><span aria-current="true">{l.upper()}</span><span aria-hidden="true">/</span><a data-language href="{url(other,altpath)}" lang="{other}" hreflang="{other}" aria-label="{'Lire en français' if l=='en' else 'Read in English'}">{other.upper()}</a></div></div></header><main id="main">{body(l,p)}</main><footer class="footer"><div class="wrap"><div class="footer-top"><div>{logo(l,True)}<p>{t['footerLine']}</p></div><div><p class="eyebrow">NIORO RESOURCES LLC</p><p>{t['location']}<br>{t['established']}</p><a href="mailto:{C['email']}">{C['email']}</a></div><nav aria-label="{'Footer navigation' if l=='en' else 'Navigation de pied de page'}">{''.join(link(l,np,lab) for np,lab in zip(navpaths,t['nav']))}</nav></div><div class="footer-bottom"><span>© 2026 Nioro Resources LLC. {t['rights']}</span>{link(l,'privacy',t['privacy'])}</div></div></footer></body></html>'''
for l in CONTENT:
 for p in PAGES:
  d=OUT/l/p;d.mkdir(parents=True,exist_ok=True);(d/'index.html').write_text(render(l,p))
(OUT/'index.html').write_text(render('en',''))
(OUT/'404.html').write_text(render('en','404'))
(OUT/'robots.txt').write_text('User-agent: *\n'+('Allow: /\nSitemap: '+C['origin']+'/sitemap.xml\n' if C['indexable'] else 'Disallow: /\n'))
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{C["origin"]+url(l,p)}</loc></url>' for l in CONTENT for p in PAGES if p!='markets')+'</urlset>')
(OUT/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Frame-Options: DENY\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n/assets/*\n  Cache-Control: public, max-age=86400\n')
shutil.copytree(ROOT/'legacy',OUT/'legacy')
(OUT/'privacy.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=/en/privacy/"><title>Privacy | Nioro Resources</title><p><a href="/en/privacy/">Privacy information / Informations de confidentialité</a></p></html>')
print(f'Built {len(CONTENT)*len(PAGES)} localized pages, root, 404, sitemap and assets.')
